import {LANGUAGES, DEFAULT_PREFS, MOODS, THEMES, escapeHTML as esc, compatibleEditions, normalizePrefs, selectPassages, needsHumanSupport, isValidEntry, audioExtension} from './core.js';
import {COPY, REFLECTIONS, STORIES} from './content.js';

const app=document.querySelector('#app'), modalRoot=document.querySelector('#modal-root');
const state={page:'journal',tab:'today',mode:'write',text:'',mood:'',audio:null,audioName:'',entries:[],activeId:null,more:false,query:'',filter:'',saving:false,storageError:false};
let editions=[],prefs={...DEFAULT_PREFS},db=null,recorder=null,stream=null,recordTimer=null,recordSeconds=0,recordStarting=false,toastTimer=null,modalFocus=null,practiceTimer=null,practiceRemaining=60;
const objectURLs=new Set();
const t=key=>COPY[prefs.language][key]??COPY.en[key]??key;
const li=()=>Object.keys(LANGUAGES).indexOf(prefs.language);
const tx=(key)=>esc(t(key));
const date=(value,short=false)=>new Intl.DateTimeFormat(prefs.language,{dateStyle:short?'medium':'full'}).format(new Date(value));
const isRecording=()=>recordStarting||recorder?.state==='recording';
const iconPaths={
  journal:'<path d="M5 4h13a2 2 0 0 1 2 2v14H6a3 3 0 0 1 0-6h14M6 4v10M9 8h7"/>',
  discover:'<circle cx="12" cy="12" r="9"/><path d="m16 8-3 5-5 3 3-5z"/>',
  book:'<path d="M12 6c-3-3-7-3-10-2v15c4-1 7-1 10 2 3-3 6-3 10-2V4c-3-1-7-1-10 2Zm0 0v15"/>',
  heart:'<path d="M20.5 4.5a5.5 5.5 0 0 0-8.5 1 5.5 5.5 0 0 0-8.5 7l8.5 8 8.5-8a5.5 5.5 0 0 0 0-8Z"/>',
  people:'<circle cx="9" cy="7" r="3"/><path d="M3 20v-3a6 6 0 0 1 12 0v3M16 4a3 3 0 0 1 0 6m2 4a5 5 0 0 1 3 5"/>',
  settings:'<circle cx="12" cy="12" r="3"/><path d="m10 2-.5 3-2 1L5 5 2 10l2.5 2L4 15l-1 1 3 5 3-1 2 2 4-1 .5-3 2-1 2.5 1 2-5-2.5-2 .5-3-3-3-3 1-2-3Z"/>',
  sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/>',
  globe:'<circle cx="12" cy="12" r="9"/><ellipse cx="12" cy="12" rx="4" ry="9"/><path d="M3 12h18"/>',
  lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V6a4 4 0 0 1 8 0v4m-4 5v2"/>',
  pen:'<path d="m15 4 5 5M4 20l5-1L21 7l-4-4L5 15z"/>',
  mic:'<rect x="9" y="2" width="6" height="13" rx="3"/><path d="M5 10v2a7 7 0 0 0 14 0v-2m-7 9v3m-4 0h8"/>',
  arrow:'<path d="M4 12h15m-6-6 6 6-6 6"/>',back:'<path d="M20 12H5m6-6-6 6 6 6"/>',
  leaf:'<path d="M4 20 18 6M5 16C-1 6 11 2 21 3c1 10-3 20-13 15m3-9v7h6"/>',
  sprout:'<path d="M12 22V10m0 6C3 16 2 10 2 6c7 0 10 4 10 10Zm0-6C12 4 17 2 22 2c0 6-3 10-10 10"/>',
  star:'<path d="m12 2 2.6 6.7L22 9l-5.6 4.8 1.8 7.2-6.2-4-6.2 4 1.8-7.2L2 9l7.4-.3z"/>',
  wave:'<path d="M2 8c4-6 7 6 11 0s7 4 9 0M2 15c4-6 7 6 11 0s7 4 9 0"/>',
  cloud:'<path d="M6 18a5 5 0 1 1 0-10 7 7 0 0 1 13-1 5.5 5.5 0 0 1 0 11Z"/>',
  moon:'<path d="M20 16A9 9 0 0 1 8 4a9 9 0 1 0 12 12Z"/>',
  rain:'<path d="M6 14a4 4 0 1 1 0-8 6 6 0 0 1 11-1 5 5 0 0 1 2 9M8 17l-1 4m6-4-1 4m6-4-1 4"/>',
  unsure:'<circle cx="12" cy="12" r="9"/><path d="M9 9a3 3 0 0 1 6 0c0 2-3 2-3 4m0 3v.1"/>',
  close:'<path d="m6 6 12 12M6 18 18 6"/>',check:'<path d="m4 12 5 5L20 6"/>',
  trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7"/>',
  download:'<path d="M12 3v12m-5-5 5 5 5-5M4 15v6h16v-6"/>',
  upload:'<path d="M12 16V4m-5 5 5-5 5 5M4 16v5h16v-5"/>',
  play:'<path d="m9 4 12 8-12 8Z"/>',stop:'<rect x="5" y="5" width="14" height="14" rx="2"/>',
  breath:'<path d="M3 8h12a3 3 0 1 0-3-3M3 12h16a3 3 0 1 1-3 3M3 16h7a3 3 0 1 1-3 3"/>',
  chat:'<path d="M21 11a9 9 0 0 1-9 9H3l1-5a9 9 0 1 1 17-4Z"/><path d="M7 10h10m-10 4h6"/>',
  hands:'<path d="m12 3-4 8-1 10m5-18 4 8 1 10M12 3v15M7 8l-3 4-1 9m14-13 3 4 1 9"/>',
};
const ico=(name,cls='')=>`<svg viewBox="0 0 24 24" aria-hidden="true" class="${cls}">${iconPaths[name]??iconPaths.leaf}</svg>`;
const moodIcon={grateful:'sun',peaceful:'leaf',hopeful:'sprout',anxious:'wave',lonely:'moon',sad:'rain',overwhelmed:'cloud',unsure:'unsure'};
const button=(label,action,cls='primary',icon='')=>`<button type="button" class="${cls}" data-action="${action}">${icon?ico(icon):''}${tx(label)}</button>`;
const languageOptions=(current)=>Object.entries(LANGUAGES).map(([id,name])=>`<option value="${id}" ${id===current?'selected':''}>${name}</option>`).join('');
const audioURL=blob=>{const url=URL.createObjectURL(blob);objectURLs.add(url);return url;};
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),5000);}
function openDB(){return new Promise((resolve,reject)=>{const request=indexedDB.open('still-journal',1);request.onupgradeneeded=()=>request.result.createObjectStore('entries',{keyPath:'id'});request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);request.onblocked=()=>reject(new Error('Storage blocked'));});}
function dbRead(){return new Promise((resolve,reject)=>{const req=db.transaction('entries').objectStore('entries').getAll();req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
function dbWrite(entry,remove=false){return new Promise((resolve,reject)=>{if(!db){reject(new Error('Storage unavailable'));return;}const tr=db.transaction('entries','readwrite');const store=tr.objectStore('entries');remove?store.delete(entry.id):store.put(entry);tr.oncomplete=resolve;tr.onerror=()=>reject(tr.error);tr.onabort=()=>reject(tr.error);});}
function persistPrefs(){try{localStorage.setItem('still-preferences',JSON.stringify(prefs));return true;}catch{toast(t('storageError'));return false;}}
function currentEntry(){return state.entries.find(e=>e.id===state.activeId);}
function currentPassages(){return selectPassages(editions,prefs,state.mood||'peaceful');}
function shell(){
  const nav=[['journal','journal'],['discover','discover'],['learn','book'],['kindness','heart'],['gather','people']];
  return `<div class="app-shell"><aside class="sidebar"><button class="brand" data-nav="journal" aria-label="Still"><img src="./assets/mark.svg" alt=""><span class="wordmark">still</span></button><span class="brand-caption">${tx('tagline')}</span><nav class="nav" aria-label="${tx('privateSpace')}">${nav.map(([id,icon])=>`<button class="nav-link ${state.page===id?'active':''}" data-nav="${id}" ${state.page===id?'aria-current="page"':''}>${ico(icon)}<span>${tx(id)}</span>${id==='gather'?`<span class="soon">${tx('soon')}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="sidebar-note">${ico('sprout')}${tx('welcome')}</div>${button('settings','settings','nav-link','settings')}${button('support','support','nav-link','heart')}</div></aside><div class="main-wrap"><header class="topbar"><div class="mobile-brand"><img src="./assets/mark.svg" alt="">still</div><div class="topbar-date">${ico('sun')}${date(new Date())}</div><div class="topbar-right"><div class="language-wrap">${ico('globe')}<label for="language" class="sr-only">${tx('interfaceLanguage')}</label><select id="language" ${isRecording()?'disabled':''}>${languageOptions(prefs.language)}</select></div><div class="privacy-chip">${ico('lock')}${tx('localOnly')}</div><button class="text-button" data-action="settings" aria-label="${tx('settings')}">${ico('settings')}</button></div></header><main class="content" id="main" tabindex="-1">${pageContent()}<footer class="footer"><span>${ico('sprout')}${tx('smallSteps')}</span><button data-action="credits">${tx('sources')}</button></footer></main></div></div>`;
}
function botanical(){return `<svg class="botanical" viewBox="0 0 160 240" aria-hidden="true"><path d="M84 240C65 170 70 102 113 25M76 170c-47-12-64-49-52-73 30 12 46 36 52 73Zm0-50c35-6 57-29 52-53-33 2-46 27-52 53ZM89 81c-30-9-40-40-31-57 26 12 32 31 31 57Zm12-30c-4-26 10-45 30-49 6 26-12 40-30 49ZM75 205c39-15 56-43 43-65-31 9-42 35-43 65Z"/></svg>`;}
function hero(){return `<section class="hero"><div class="eyebrow">${tx('privateSpace')}</div><h1>${tx('hero')}</h1><p>${tx('heroSub')}</p>${botanical()}</section>`;}
function rail(){if(currentEntry()?.support)return '';const p=currentPassages()[0];return `<aside class="right-rail"><section class="verse-card">${ico('book','verse-icon')}<div class="eyebrow">${tx('verseDay')}</div>${p?`<blockquote lang="${p.language}">“${esc(p.text)}”</blockquote><div class="reference">${esc(p.reference)}</div><div class="edition">${esc(p.editionName)}</div><a class="verse-link" href="${esc(p.sourceUrl)}" target="_blank" rel="noopener noreferrer">${tx('source')}${ico('arrow')}</a>${p.editionId==='blivre'?`<div class="mini-note">${esc(p.attribution)} <a href="${esc(p.licenseUrl)}" target="_blank" rel="noopener noreferrer">CC BY 4.0</a></div>`:''}`:`<p class="subtitle">${tx('unavailable')}</p>${button('settings','settings','text-button','arrow')}`}</section><section class="moment-card"><img class="moment-image" src="./assets/landscape.svg" alt=""><div class="moment-body"><h3>${tx('quietMoment')}</h3><p>${tx('quietSub')}</p>${button('takeMoment','breathe','text-button','play')}</div></section><div class="reminder"><div class="eyebrow">${tx('gentleReminder')}</div><p>${tx('reminder')}</p>${ico('sprout')}</div></aside>`;}
function pageContent(){
  if(state.page==='journal')return `<div class="page-grid"><div>${state.activeId?journey(currentEntry()):`${hero()}<div class="journal-tabs" role="tablist"><button role="tab" aria-selected="${state.tab==='today'}" class="${state.tab==='today'?'active':''}" data-tab="today">${ico('pen')}${tx('newEntry')}</button><button role="tab" aria-selected="${state.tab==='history'}" class="${state.tab==='history'?'active':''}" data-tab="history">${ico('journal')}${tx('history')}<span class="count">${state.entries.length}</span></button></div>${state.tab==='today'?composer():history()}`}</div>${rail()}</div>`;
  if(state.page==='discover')return `<header class="page-header"><div class="eyebrow">${tx('discover')}</div><h1>${tx('discoverTitle')}</h1><p>${tx('discoverSub')}</p></header><div class="practice-eyebrow">${tx('timeless')}</div><div class="cards-grid">${STORIES.map(s=>`<article class="story-card"><div class="story-art ${s.color}">${ico(s.icon)}</div><div class="story-body"><div class="story-meta">${esc(s.source)} · ${s.year}</div><h2>${esc(s.titles[li()])}</h2><p>${esc(s.summaries[li()])}</p><a href="${s.url}" target="_blank" rel="noopener noreferrer">${tx('readStory')}${ico('arrow')}</a></div></article>`).join('')}</div><p class="collection-end">${tx('collectionEnd')}</p>`;
  if(state.page==='learn')return `<header class="page-header"><div class="eyebrow">${tx('learn')}</div><h1>${tx('learnTitle')}</h1><p>${tx('learnSub')}</p></header><div class="practice-eyebrow">${tx('originalPractice')}</div><div class="cards-grid">${[['breathe','breath',1],['pray','hands',2],['gratitudePractice','sun',3]].map(([id,icon,mins])=>`<article class="practice-card"><div class="icon-bubble">${ico(icon)}</div><div class="eyebrow">${mins} ${tx('minute')}</div><h2>${tx(id)}</h2><p>${tx(id==='gratitudePractice'?'gratitudeDesc':id+'Desc')}</p>${button('begin',id,'text-button','arrow')}</article>`).join('')}</div>`;
  if(state.page==='kindness')return `<header class="page-header"><div class="eyebrow">${tx('kindness')}</div><h1>${tx('kindnessTitle')}</h1><p>${tx('kindnessSub')}</p></header><div class="cards-grid">${[['thankAction','sun'],['listenAction','chat'],['helpAction','heart']].map(([id,icon])=>`<article class="practice-card"><div class="icon-bubble">${ico(icon)}</div><h2>${tx(id)}</h2><p>${tx(id+'Desc')}</p>${button('returnJournal','journal','text-button','arrow')}</article>`).join('')}</div><p class="note-box">${tx('noListings')}</p>`;
  return `<header class="page-header"><div class="eyebrow">${tx('gather')} · ${tx('soon')}</div><h1>${tx('gatherTitle')}</h1><p>${tx('gatherSub')}</p></header><section class="gather-empty"><div class="icon-bubble">${ico('people')}</div><h2>${tx('welcome')}</h2><p>${tx('gatherBody')}</p>${button('support','support','secondary','heart')}</section>`;
}
function audioPreview(blob,removable=false){return `<div class="audio-preview"><span>${ico('mic')} ${tx('audioEntry')}</span>${removable?`<button data-action="remove-audio" aria-label="${tx('removeAudio')}">${ico('close')}${tx('removeAudio')}</button>`:''}<audio controls preload="metadata" src="${audioURL(blob)}" aria-label="${tx('audioEntry')}"></audio></div>`;}
function composer(){return `<section class="checkin"><h2>${tx('heart')}</h2><p class="subtitle">${tx('heartSub')}</p><div class="mood-grid" role="group" aria-label="${tx('heart')}">${MOODS.map(m=>`<button class="mood ${state.mood===m?'selected':''}" data-mood="${m}" aria-pressed="${state.mood===m}" ${isRecording()?'disabled':''}>${ico(moodIcon[m])}${tx(m)}</button>`).join('')}</div><div class="composer"><div class="composer-tabs" role="tablist"><button role="tab" aria-selected="${state.mode==='write'}" class="${state.mode==='write'?'active':''}" data-mode="write" ${isRecording()?'disabled':''}>${ico('pen')}${tx('write')}</button><button role="tab" aria-selected="${state.mode==='voice'}" class="${state.mode==='voice'?'active':''}" data-mode="voice">${ico('mic')}${tx('voice')}</button></div>${state.mode==='write'?`<label class="sr-only" for="entry-text">${tx('entryLabel')}</label><textarea id="entry-text" maxlength="10000" placeholder="${tx('prompt')}">${esc(state.text)}</textarea>`:`<div class="record-area"><h3>${tx('recordTitle')}</h3><p>${tx('recordHelp')}</p>${isRecording()?`<div class="record-time"><span class="record-dot"></span><span id="record-clock">00:00</span></div>`:''}<div class="record-controls">${button(isRecording()?'stop':'record',isRecording()?'stop-record':'record','primary',isRecording()?'stop':'mic')}<label class="secondary" for="audio-upload">${ico('upload')}${tx('upload')}</label><input class="sr-only" id="audio-upload" type="file" accept="audio/*" ${isRecording()?'disabled':''}></div></div>`}${state.audio?audioPreview(state.audio,true):''}<div class="composer-bottom"><span>${ico('lock')}${tx('localOnly')}</span><span><span id="char-count">${state.text.length}</span> / 10,000</span></div></div>${state.storageError?`<div class="error-banner" role="alert">${tx('storageError')} ${button('exportDraft','export-draft','text-button','download')}</div>`:''}<button class="primary full continue" data-action="save-entry" ${state.saving||isRecording()?'disabled':''}>${tx(state.saving?'saving':'continue')}${ico('arrow')}</button><p class="privacy-foot">${tx('privacyNote')}</p></section>`;}
function history(){return `<section class="checkin"><h2>${tx('history')}</h2><p class="subtitle">${tx('historySub')}</p>${state.entries.length?`<div class="search-row"><label for="search" class="sr-only">${tx('search')}</label><input type="search" id="search" placeholder="${tx('search')}" value="${esc(state.query)}"><label for="filter" class="sr-only">${tx('allFeelings')}</label><select id="filter"><option value="">${tx('allFeelings')}</option>${MOODS.map(m=>`<option value="${m}" ${state.filter===m?'selected':''}>${tx(m)}</option>`).join('')}</select></div><div class="entry-list" id="entry-list">${historyRows()}</div>`:`<div class="empty"><div class="icon-bubble">${ico('journal')}</div><h2>${tx('emptyTitle')}</h2><p>${tx('emptySub')}</p>${button('firstEntry','new','primary','pen')}</div>`}</section>`;}
function historyRows(){const entries=state.entries.filter(e=>(!state.filter||e.mood===state.filter)&&(!state.query||`${e.text} ${e.followup?.text||''} ${t(e.mood||'unsure')}`.toLocaleLowerCase(prefs.language).includes(state.query.toLocaleLowerCase(prefs.language))));return entries.length?entries.map(e=>`<button class="entry-row" data-entry="${esc(e.id)}"><div class="icon-bubble">${ico(moodIcon[e.mood]??'journal')}</div><div class="row-copy"><div class="entry-date">${date(e.createdAt,true)}</div><div class="entry-summary">${esc(e.text.trim().split('\n')[0]||t(e.audio?'audioEntry':e.mood||'newEntry'))}</div><div class="entry-meta">${e.mood?tx(e.mood):''}${e.audio?ico('mic'):''}${e.followup?ico('check'):''}</div></div>${ico('arrow')}</button>`).join(''):`<p class="subtitle">${tx('noResults')}</p>`;}
function passageCard(p){return `<section class="passage"><div class="eyebrow">${tx('verseDay')}</div><blockquote lang="${p.language}">“${esc(p.text)}”</blockquote><div class="reference" lang="${p.language}">${esc(p.reference)}</div><div class="edition">${esc(p.editionName)}</div><a class="verse-link" href="${esc(p.sourceUrl)}" target="_blank" rel="noopener noreferrer">${tx('source')}${ico('arrow')}</a>${p.context?.[prefs.language]?`<p class="passage-context">${esc(p.context[prefs.language])}</p>`:''}${p.editionId==='blivre'?`<p class="attribution">${esc(p.attribution)} <a href="${esc(p.licenseUrl)}" target="_blank" rel="noopener noreferrer">CC BY 4.0</a></p>`:''}</section>`;}
function supportContent(){return `<div class="support-box"><h2>${tx('supportTitle')}</h2><p>${tx('supportDesc')}</p><p>${tx('supportBoundary')}</p></div>`;}
function actionOptions(entry){const options=entry.mood==='grateful'?['thankAction','prayerAction','walkAction']:entry.mood==='lonely'?['reachAction','prayerAction','walkAction']:['prayerAction','walkAction','reachAction'];return options.map(id=>`<button class="action-option ${entry.action===id?'chosen':''}" data-step="${id}" aria-pressed="${entry.action===id}"><div class="icon-bubble">${ico(id==='prayerAction'?'hands':id==='walkAction'?'leaf':id==='thankAction'?'sun':'chat')}</div><span class="action-copy"><strong>${tx(id)}</strong><small>${tx(id+'Desc')}</small></span>${ico(entry.action===id?'check':'arrow')}</button>`).join('');}
function journey(entry){if(!entry)return '';return `<article class="journey"><div class="journey-header">${button('back','history','text-button','back')}<span class="success-tag">${ico('check')}${tx('saved')}</span></div><div class="eyebrow">${date(entry.createdAt,true)}${entry.mood?' · '+tx(entry.mood):''}</div><h1>${tx('reflected')}</h1><p class="subtitle">${tx(entry.support?'supportBoundary':'curated')}</p>${state.storageError?`<div class="error-banner" role="alert">${tx('storageError')} ${button('export','export','text-button','download')}</div>`:''}<details class="original-entry"><summary>${tx('original')}</summary>${entry.text?`<p class="entry-text">${esc(entry.text)}</p>`:''}${entry.audio?audioPreview(entry.audio):''}</details>${entry.support?supportContent():`${entry.passages.length?passageCard(entry.passages[0]):`<div class="note-box">${tx('unavailable')}</div>`}${entry.passages.length?`<div class="reflection"><div class="eyebrow">${tx('editorial')}</div><p lang="${entry.language}">${esc(entry.reflection)}</p></div>`:''}${entry.passages.length>1?`<button class="text-button" data-action="more-verses" aria-expanded="${state.more}">${ico('book')}${tx('moreVerses')}${ico('arrow')}</button>${state.more?`<div class="more-passages">${entry.passages.slice(1).map(passageCard).join('')}</div>`:''}`:''}<section class="action-section"><h2>${tx('nextStep')}</h2><p class="subtitle">${tx('nextSub')}</p><div class="action-options">${actionOptions(entry)}</div>${entry.action==='prayerAction'?`<p class="prayer-text">${esc(entry.actionText||t('prayDesc'))}</p><p class="mini-note">${tx('originalPractice')}</p>`:''}${button('skip','history','text-button')}</section><section class="followup"><h2>${tx('followup')}</h2><p class="subtitle">${tx('followSub')}</p><div class="follow-options" role="group" aria-label="${tx('followup')}">${['lighter','same','heavier'].map(id=>`<button data-feeling="${id}" aria-pressed="${entry.followDraft?.feeling===id}" class="${entry.followDraft?.feeling===id?'selected':''}">${tx(id)}</button>`).join('')}</div><label class="sr-only" for="follow-text">${tx('followup')}</label><textarea id="follow-text" maxlength="5000" placeholder="${tx('followPlaceholder')}">${esc(entry.followDraft?.text??'')}</textarea>${button('saveFollow','save-follow','primary','check')}${entry.followup?`<p class="mini-note">${tx('saved')} · ${date(entry.followup.updatedAt,true)}</p>`:''}</section>`}<div class="entry-actions">${button('newThought','new','text-button','pen')}${button('delete','delete','text-button danger','trash')}</div>${entry.audio?button('downloadAudio','download-audio','text-button','download'):''}</article>`;}
function render(){objectURLs.forEach(url=>URL.revokeObjectURL(url));objectURLs.clear();document.documentElement.lang=prefs.language;document.title=`Still · ${t(state.page)}`;document.querySelector('.skip-link').textContent=t('journal');app.innerHTML=shell();}
function focusMain(){document.querySelector('#main')?.focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}
function navigate(page,tab){if(isRecording()){toast(t('stop'));return;}state.page=page;state.activeId=null;if(tab)state.tab=tab;render();focusMain();}
function closeModal(){const dialog=modalRoot.querySelector('dialog');if(dialog?.open)dialog.close();clearInterval(practiceTimer);practiceTimer=null;modalRoot.innerHTML='';modalFocus?.focus?.();}
function modal(title,body,kind=''){if(isRecording()){toast(t('stop'));return;}modalFocus=document.activeElement;modalRoot.innerHTML=`<dialog data-kind="${kind}" aria-labelledby="modal-title"><div class="modal-header"><h2 id="modal-title">${tx(title)}</h2><button data-action="close-modal" aria-label="${tx('close')}">${ico('close')}</button></div><div class="modal-body">${body}</div></dialog>`;const dialog=modalRoot.querySelector('dialog');dialog.addEventListener('cancel',e=>{e.preventDefault();closeModal();});dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});dialog.showModal();}
function settings(){const options=compatibleEditions(editions,prefs),edition=options.find(e=>e.id===prefs.edition);modal('settings',`<p>${tx('preferencesSub')}</p><div class="form-field"><label for="pref-language">${tx('interfaceLanguage')}</label><select id="pref-language" data-pref="language">${languageOptions(prefs.language)}</select></div><div class="form-field"><label for="pref-tradition">${tx('tradition')}</label><select id="pref-tradition" data-pref="tradition">${['protestant','catholic','orthodox'].map(id=>`<option value="${id}" ${prefs.tradition===id?'selected':''}>${tx(id)}</option>`).join('')}</select></div><div class="form-field"><label for="pref-scriptureLanguage">${tx('scriptureLanguage')}</label><select id="pref-scriptureLanguage" data-pref="scriptureLanguage">${languageOptions(prefs.scriptureLanguage)}</select></div><div class="form-field"><label for="pref-edition">${tx('edition')}</label><select id="pref-edition" data-pref="edition" ${options.length?'':'disabled'}>${options.length?options.map(e=>`<option value="${esc(e.id)}" ${prefs.edition===e.id?'selected':''}>${esc(e.name)}</option>`).join(''):`<option>${tx('unavailableShort')}</option>`}</select></div><p class="help">${tx('editionHelp')}</p>${edition?`<p class="help">${esc(edition.scope)}</p>`:`<p class="note-box">${tx('unavailable')}</p>`}<div class="modal-section"><h3>${tx('privacyTitle')}</h3><p>${tx('privacyDetail')}</p>${button('export','export','secondary','download')}<p class="help">${tx('exportHelp')}</p></div><div class="modal-actions">${button('close','close-modal')}</div>`,'settings');}
function credits(){modal('sources',`<p>${tx('sourcesSub')}</p>${editions.map(e=>`<section class="credit-entry"><h3>${esc(e.name)}</h3><p>${esc(e.scope)}</p><p>${esc(e.attribution)}</p><a href="${esc(e.sourceUrl)}" target="_blank" rel="noopener noreferrer">${tx('source')}</a> · <a href="${esc(e.licenseUrl)}" target="_blank" rel="noopener noreferrer">${esc(e.license)}</a></section>`).join('')}<section class="credit-entry"><p>Still · MVP 0.1 · ${tx('originalPractice')}</p><p>${tx('privacyNote')}</p></section>`);}
function showSupport(fromSave=false){modal('support',`${supportContent()}${fromSave?`<div class="modal-actions">${button('cancel','close-modal','secondary')}${button('supportSave','save-support')}</div>`:''}`,'support');}
function showPractice(id){practiceRemaining=60;const prayer=id==='pray',gratitude=id==='gratitudePractice';modal(id,`<div class="practice-eyebrow">${tx('originalPractice')}</div>${prayer?`<p class="prayer-text">${tx('prayDesc')}</p>`:gratitude?`<p>${tx('gratitudeDesc')}</p>`:`<div class="breath-wrap"><div class="breath-circle" id="breath-circle"><span id="practice-time">1:00</span></div><p>${tx('breatheDesc')}</p><button class="primary" data-action="timer" id="timer-button">${tx('begin')}</button></div>`}<div class="modal-actions">${button('returnJournal','journal','secondary','pen')}</div>`,'practice');}

async function saveEntry(support=false){
  if(state.saving||isRecording())return;
  if(!isValidEntry(state.text,state.mood,state.audio)){toast(t('needEntry'));return;}
  if(!support&&needsHumanSupport(state.text)){showSupport(true);return;}
  state.saving=true;render();
  const theme=THEMES[state.mood]??'hope';
  const entry={id:crypto.randomUUID(),createdAt:new Date().toISOString(),text:state.text.trim(),mood:state.mood,audio:state.audio,audioName:state.audioName,language:prefs.language,preferences:{...prefs},support,passages:support?[]:selectPassages(editions,prefs,state.mood),reflection:REFLECTIONS[theme][li()],action:null,followup:null};
  try{await dbWrite(entry);state.entries.unshift(entry);state.text='';state.mood='';state.audio=null;state.audioName='';state.activeId=entry.id;state.more=false;state.storageError=false;toast(t('saved'));}
  catch{state.storageError=true;toast(t('storageError'));}
  finally{state.saving=false;render();focusMain();}
}
async function updateEntry(updated){try{await dbWrite(updated);const index=state.entries.findIndex(e=>e.id===updated.id);state.entries[index]=updated;state.storageError=false;return true;}catch{state.storageError=true;toast(t('storageError'));return false;}}
async function saveFollow(){const e=currentEntry();if(!e)return;const draft=e.followDraft??{};if(!draft.feeling&&!draft.text?.trim()){toast(t('needEntry'));return;}const support=needsHumanSupport(draft.text??'');const updated={...e,followup:{feeling:draft.feeling??'',text:draft.text?.trim()??'',updatedAt:new Date().toISOString()},support:e.support||support};delete updated.followDraft;if(await updateEntry(updated)){updated.followDraft={...updated.followup};render();toast(t('saved'));if(support)showSupport();}}
async function startRecording(){
  if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){toast(t('noRecorder'));return;}
  if(isRecording())return;recordStarting=true;
  try{
    stream=await navigator.mediaDevices.getUserMedia({audio:true});
    const mime=['audio/webm;codecs=opus','audio/mp4','audio/ogg;codecs=opus'].find(m=>MediaRecorder.isTypeSupported(m));
    recorder=new MediaRecorder(stream,mime?{mimeType:mime}:undefined);const chunks=[];
    recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};
    recorder.onstop=()=>{clearInterval(recordTimer);stream?.getTracks().forEach(track=>track.stop());stream=null;recordStarting=false;const blob=new Blob(chunks,{type:recorder.mimeType||chunks[0]?.type||'audio/webm'});if(blob.size){state.audio=blob;state.audioName=`still-recording.${audioExtension(blob.type)}`;}recorder=null;render();if(blob.size)toast(t('audioReady'));};
    recorder.onerror=()=>{clearInterval(recordTimer);stream?.getTracks().forEach(track=>track.stop());stream=null;recordStarting=false;toast(t('micError'));};
    recorder.start(500);recordStarting=false;recordSeconds=0;render();
    recordTimer=setInterval(()=>{recordSeconds++;const el=document.querySelector('#record-clock');if(el)el.textContent=`${String(Math.floor(recordSeconds/60)).padStart(2,'0')}:${String(recordSeconds%60).padStart(2,'0')}`;if(recordSeconds>=120)stopRecording();},1000);
  }catch{recordStarting=false;stream?.getTracks().forEach(track=>track.stop());stream=null;toast(t('micError'));render();}
}
function stopRecording(){if(recorder?.state==='recording')recorder.stop();clearInterval(recordTimer);stream?.getTracks().forEach(track=>track.stop());}
function download(content,name,type){const blob=content instanceof Blob?content:new Blob([content],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
function serializeAudio(blob){return new Promise((resolve,reject)=>{if(!blob){resolve(null);return;}const reader=new FileReader();reader.onload=()=>resolve({type:blob.type,dataUrl:reader.result});reader.onerror=()=>reject(reader.error);reader.readAsDataURL(blob);});}
async function exportJournal(draft=false){try{const list=draft?[{text:state.text,mood:state.mood,audio:state.audio,audioName:state.audioName}]:state.entries;const entries=[];for(const entry of list){const{audio,followDraft,...rest}=entry;entries.push({...rest,...(followDraft?{unsavedFollowup:followDraft}:{}),audio:await serializeAudio(audio)});}download(JSON.stringify({format:'still-journal',version:1,exportedAt:new Date().toISOString(),preferences:prefs,entries},null,2),`still-${draft?'draft':'journal'}-${new Date().toISOString().slice(0,10)}.json`,'application/json');}catch{toast(t('storageError'));}}
function toggleTimer(){const btn=document.querySelector('#timer-button'),circle=document.querySelector('#breath-circle');if(practiceTimer){clearInterval(practiceTimer);practiceTimer=null;circle.classList.remove('running');btn.textContent=t('resume');return;}if(practiceRemaining===0)practiceRemaining=60;btn.textContent=t('pause');circle.classList.add('running');practiceTimer=setInterval(()=>{practiceRemaining--;document.querySelector('#practice-time').textContent=`${Math.floor(practiceRemaining/60)}:${String(practiceRemaining%60).padStart(2,'0')}`;if(practiceRemaining===0){clearInterval(practiceTimer);practiceTimer=null;circle.classList.remove('running');btn.textContent=t('begin');toast(t('complete'));}},1000);}

document.addEventListener('click',async event=>{
  const el=event.target.closest('button');if(!el||el.disabled)return;
  if(el.dataset.nav){navigate(el.dataset.nav);return;}
  if(el.dataset.tab){navigate('journal',el.dataset.tab);return;}
  if(el.dataset.mode){if(!isRecording()){state.mode=el.dataset.mode;render();}return;}
  if(el.dataset.mood){state.mood=state.mood===el.dataset.mood?'':el.dataset.mood;render();document.querySelector(`[data-mood="${el.dataset.mood}"]`)?.focus();return;}
  if(el.dataset.entry){state.activeId=el.dataset.entry;state.more=false;const e=currentEntry();e.followDraft=e.followDraft??{...e.followup};render();focusMain();return;}
  if(el.dataset.step){const e=currentEntry(),updated={...e,action:el.dataset.step,actionText:t(el.dataset.step==='prayerAction'?'prayDesc':el.dataset.step+'Desc')};if(await updateEntry(updated)){render();toast(t('selected'));}return;}
  if(el.dataset.feeling){const e=currentEntry();e.followDraft={...e.followDraft,feeling:el.dataset.feeling};document.querySelectorAll('[data-feeling]').forEach(b=>{b.classList.toggle('selected',b.dataset.feeling===el.dataset.feeling);b.setAttribute('aria-pressed',String(b.dataset.feeling===el.dataset.feeling));});return;}
  switch(el.dataset.action){
    case 'settings':settings();break;case 'credits':credits();break;case 'support':showSupport();break;
    case 'close-modal':closeModal();break;
    case 'save-entry':await saveEntry();break;
    case 'save-support':closeModal();await saveEntry(true);break;
    case 'record':await startRecording();break;case 'stop-record':stopRecording();break;
    case 'remove-audio':if(!isRecording()){state.audio=null;state.audioName='';render();}break;
    case 'new':state.mode='write';navigate('journal','today');break;
    case 'history':navigate('journal','history');break;
    case 'journal':closeModal();navigate('journal','today');break;
    case 'more-verses':state.more=!state.more;render();break;
    case 'save-follow':await saveFollow();break;
    case 'delete':modal('deleteTitle',`<p>${tx('deleteDesc')}</p><div class="modal-actions">${button('cancel','close-modal','secondary')}${button('delete','confirm-delete','primary')}</div>`);break;
    case 'confirm-delete':{const e=currentEntry();try{await dbWrite(e,true);state.entries=state.entries.filter(x=>x.id!==e.id);closeModal();navigate('journal','history');}catch{toast(t('storageError'));}break;}
    case 'export':await exportJournal();break;case 'export-draft':await exportJournal(true);break;
    case 'download-audio':{const e=currentEntry();download(e.audio,`still-${e.id}.${audioExtension(e.audio.type)}`);break;}
    case 'breathe':case 'pray':case 'gratitudePractice':showPractice(el.dataset.action);break;
    case 'timer':toggleTimer();break;
  }
});
document.addEventListener('input',event=>{const el=event.target;if(el.id==='entry-text'){state.text=el.value;document.querySelector('#char-count').textContent=el.value.length;}if(el.id==='follow-text'){const e=currentEntry();e.followDraft={...e.followDraft,text:el.value};}if(el.id==='search'){state.query=el.value;document.querySelector('#entry-list').innerHTML=historyRows();}});
document.addEventListener('change',event=>{
  const el=event.target;
  if(el.id==='language'){prefs.language=el.value;persistPrefs();render();return;}
  if(el.dataset.pref){const key=el.dataset.pref;prefs=normalizePrefs({...prefs,[key]:el.value},editions);persistPrefs();closeModal();render();settings();document.querySelector(`[data-pref="${key}"]`)?.focus();return;}
  if(el.id==='filter'){state.filter=el.value;document.querySelector('#entry-list').innerHTML=historyRows();return;}
  if(el.id==='audio-upload'){const file=el.files?.[0];if(!file)return;if(!file.type.startsWith('audio/')||file.size>20*1024*1024||!file.size){toast(t('invalidAudio'));el.value='';return;}state.audio=file;state.audioName=file.name;render();toast(t('audioReady'));}
});
window.addEventListener('beforeunload',event=>{if(state.text.trim()||state.audio||isRecording()){event.preventDefault();event.returnValue='';}});
window.addEventListener('pagehide',()=>{clearInterval(recordTimer);clearInterval(practiceTimer);stream?.getTracks().forEach(track=>track.stop());});

async function init(){
  try{const response=await fetch('./scripture.json');if(!response.ok)throw new Error('Scripture unavailable');editions=(await response.json()).editions;}catch{editions=[];}
  try{prefs=normalizePrefs(JSON.parse(localStorage.getItem('still-preferences')||'null')??DEFAULT_PREFS,editions);}catch{prefs=normalizePrefs(DEFAULT_PREFS,editions);}
  try{db=await openDB();db.onversionchange=()=>{db.close();db=null;state.storageError=true;toast(t('storageError'));};state.entries=(await dbRead()).sort((a,b)=>b.createdAt.localeCompare(a.createdAt));}catch{state.storageError=true;}
  render();
}
init();
